import json
def f(grid):
    H,W=len(grid),len(grid[0])
    bg=grid[0][0]
    pts=[]
    for y in range(H):
        for x in range(W):
            if grid[y][x]!=bg: pts.append((y,x))
    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    newy=min(ys)+(H-h); newx=0
    out=[row[:] for row in grid]
    for y,x in pts:
        out[newy+(y-min(ys))][newx+x-min(xs)]=grid[y][x]
    return out
