def comps_g(grid,bg):
    H,W=len(grid),len(grid[0]);seen=set();res=[]
    for y in range(H):
        for x in range(W):
            if grid[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]);seen.add((y,x));gr=[]
                while q:
                    yy,xx=q.popleft();gr.append((yy,xx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=yy+dy,xx+dx
                            if 0<=ny<H and 0<=nx<W and grid[ny][nx]!=bg and (ny,nx) not in seen:
                                seen.add((ny,nx));q.append((ny,nx))
                res.append(gr)
    return res
cs=comps_g(ti,3); cs.sort(key=len,reverse=True)
