        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def comps(grid,bg):
    H,W=len(grid),len(grid[0]);seen=set();res=[]
    for y in range(H):
        for x in range(W):
            if grid[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]);seen.add((y,x));gr=[]
                while q:
                    yy,xx=q.popleft();gr.append((yy,xx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=yy+dy,xx+dx
                            if 0<=ny<H and 0<=nx<W and grid[ny][nx]!=bg and (ny,nx) not in seen:
                                seen.add((ny,nx));q.append((ny,nx))
                res.append(gr)
    return res
def f(g):
    H=len(g);W=len(g[0]);bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps(g,bg);cs.sort(key=len,reverse=True)
    p=cs[0];markers=[c for c in cs if len(c)<len(p)]
    o=[[bg]*W for _ in range(H)]
    py=int(round(sum(y for y,_ in p)/len(p))); px=int(round(sum(x for _,x in p)/len(p)))
    for y,x in p: o[y][x]=g[y][x]
    for m in markers:
        cy,mx=int(m[0][0]),int(m[0][1])
        dy=cy-py; dx=mx-px
        for y2,x2 in p:
            ny=y2+dy; nx=x2+dx
            if 0<=ny<H and 0<=nx<W: o[ny][nx]=g[int(y2)][int(x2)]
    return o
