def f_anchor(g,anchor_fn):
    H=len(g);W=len(g[0]);bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps(g,bg);cs.sort(key=len,reverse=True);p=cs[0];markers=[c for c in cs if len(c)<len(p)]
    o=[[bg]*W for _ in range(H)]
    for y,x in p:o[y][x]=g[y][x]
    for m in markers:
        cy,mx=m[0][0],m[0][1]
        py,px=anchor_fn(p)
        dy=cy-py;dx=mx-px
        for y2,x2 in p:
            ny=y2+dy;nx=x2+dx
            if 0<=ny<H and 0<=nx<W: o[ny][nx]=g[int(y2)][int(x2)]
    return o
def an_roundcentroid(p):
    ys=[y for y,_ in p];xs=[x for _,x in p]
    return int(round(sum(ys)/len(ys))),int(round(sum(xs)/len(xs)))
def an_bboxmin(p):
    ys=[y for y,_ in p];xs=[x for _,x in p]
    return min(ys),min(xs)
def an_topright(p):
    ys=[y for y,_ in p];xs=[x for _,x in p]
    return max(ys),max(xs)
def an_midpoint(p):
    ys=[y for y,_ in p];xs=[x for _,x in p]
    return (min(ys)+max(ys))//2,(min(xs)+max(xs))//2
